pub mod batch {
use super::multiproof;
use aspis_core::{r0::merkle,Digest32};
use aspis_core::state_only_private_merkle::private_leaf_hash_with_digest;
pub(crate) fn batch_keys(queries: &[u32; 22], lo: usize, n: usize, tree: usize) -> [u64; multiproof::MAX_BATCH] {
    let mut keys = [0u64; multiproof::MAX_BATCH];
    for j in 0..n {
        let u = queries[lo + j];
        let index = if tree == 2 { u / 4 } else { u };
        keys[j] = (u64::from(index) << 8) | j as u64;
    }
    keys
}
pub(crate) fn sort_batch_keys(mut keys: [u64; multiproof::MAX_BATCH], n: usize) -> [u64; multiproof::MAX_BATCH] {
    for i in 1..n {
        let mut j = i;
        while j > 0 && batch_key_at(&keys, j - 1) > batch_key_at(&keys, j) {
            keys.swap(j - 1, j);
            j -= 1;
        }
    }
    keys
}
pub(crate) fn batch_leaf<H: Digest32>(hash: H, tree: usize, q: &[u8]) -> [u8; 32] {
    match tree {
        0 => {
            let salt: [u8; 32] = q[608..640].try_into().unwrap();
            private_leaf_hash_with_digest(hash, merkle::C1_TAG, &q[..480], &salt)
        }
        1 => {
            let salt: [u8; 32] = q[640..672].try_into().unwrap();
            private_leaf_hash_with_digest(hash, merkle::C2_TAG, &q[480..608], &salt)
        }
        _ => {
            let salt: [u8; 32] = q[800..832].try_into().unwrap();
            private_leaf_hash_with_digest(hash, 0x72, &q[672..800], &salt)
        }
    }
}
pub(crate) fn same_batch_leaf(values: &[[u8; 32]; multiproof::MAX_BATCH], index: usize, leaf: [u8; 32]) -> bool {
    values[index] == leaf
}
pub(crate) fn same_batch_index(values: &[u32; multiproof::MAX_BATCH], index: usize, expected: u32) -> bool {
    values[index] == expected
}
pub(crate) fn batch_key_at(keys: &[u64; multiproof::MAX_BATCH], index: usize) -> u64 {
    keys[index]
}
pub(crate) fn sort_insert_step(mut keys:[u64;multiproof::MAX_BATCH],i:usize)->(bool,[u64;multiproof::MAX_BATCH],usize) {
        let mut j = i;
        if j > 0 && batch_key_at(&keys, j - 1) > batch_key_at(&keys, j) {
            keys.swap(j - 1, j);
            j -= 1;
            (true,keys,j)
        } else {(false,keys,j)}
}

pub(crate) fn leaf_insert(idx:&mut [u32;16],val:&mut [[u8;32];16],d:&mut usize,index:u32,leaf:[u8;32])->bool {
        if *d > 0 && same_batch_index(idx, *d - 1, index) {
            if !same_batch_leaf(val, *d - 1, leaf) {
                return false;
            }
            return true;
        }
        idx[*d] = index;
        val[*d] = leaf;
        *d += 1;
true
}

#[cfg(kani)]
pub(crate) fn leaf_batch_iteration(keys:[u64;16],mut key_position:usize,lo:usize,tree:usize,q:&[u8;832],idx:&mut [u32;16],val:&mut [[u8;32];16],d:&mut usize,answer:[u8;32],coordinate:usize)->(bool,usize,usize,usize,u8) {
        let key = batch_key_at(&keys, key_position);
        key_position += 1;
        let index = (key >> 8) as u32;
        let selected = lo + (key & 0xff) as usize;
        let observation = crate::adoption::leaf_hash(tree,q,answer,coordinate);
        let leaf = observation.digest;
        if *d > 0 && same_batch_index(idx, *d - 1, index) {
            if !same_batch_leaf(val, *d - 1, leaf) {
                return (false,key_position,selected,observation.calls,observation.event);
            }
            return (true,key_position,selected,observation.calls,observation.event);
        }
        idx[*d] = index;
        val[*d] = leaf;
        *d += 1;
(true,key_position,selected,observation.calls,observation.event)
}

}
pub mod parser {
 use super::compact::{self,CodecError,OPENING};
 use aspis_core::field::{M31,QM31 as K,WideExact as E};
 #[derive(Clone,Copy,Debug,PartialEq,Eq)] pub enum Variant {S2}
 impl Variant {fn tag(self)->u8 {2}}
 #[derive(Debug)] pub enum Error {Parse}
 impl From<CodecError> for Error {fn from(_:CodecError)->Self{Self::Parse}}
fn echeck(b:&[u8],k:bool)->Result<(),Error> {
    for c in b.chunks_exact(32) {let x=E::from_le_bytes(c).ok_or(Error::Parse)?;if k&&x.c1()!=K::ZERO {return Err(Error::Parse);}}
    Ok(())
}
fn opening(proof: &[u8], i: usize) -> &[u8] {
    let at = compact::OFF_OPENINGS + i * OPENING;
    &proof[at..at + OPENING]
}
pub fn parse_shape(proof: &[u8]) -> Result<Variant, Error> {
    if proof.len() != compact::PROOF_BYTES
        || &proof[..8] != compact::MAGIC
        || proof[8] != Variant::S2.tag()
        || proof[9..16].iter().any(|&x| x != 0)
    {
        return Err(Error::Parse);
    }
    Ok(Variant::S2)
}
pub(crate) fn canonical_scan(proof: &[u8]) -> Result<(), Error> {
    compact::check_values(&proof[compact::OFF_Y1..compact::OFF_INACTIVE])?;
    echeck(&proof[compact::OFF_INACTIVE..compact::OFF_INACTIVE + 32], false)?;
    echeck(&proof[compact::OFF_ROUND0..compact::OFF_FOLDED_ROOT], false)?;
    echeck(&proof[compact::OFF_ROUND1..compact::OFF_OPENINGS], false)?;
    for i in 0..22 {
        let q = opening(proof, i);
        for s in 0..4 {
            for l in 0..26 {
                M31::from_le_bytes(q[s * 120 + l * 4..s * 120 + l * 4 + 4].try_into().unwrap()).ok_or(Error::Parse)?;
            }
            K::from_le_bytes(&q[s * 120 + 104..s * 120 + 120]).ok_or(Error::Parse)?;
            for l in 0..2 {
                K::from_le_bytes(&q[480 + s * 32 + l * 16..480 + s * 32 + l * 16 + 16]).ok_or(Error::Parse)?;
            }
        }
        echeck(&q[672..800], false)?;
    }
    Ok(())
}
}
